using namespace std;

// Function to open a file and return the file stream
ifstream openFile(const char *filename) {
    ifstream infile;
    infile.open(filename);
    if (!infile.is_open()) {
        throw "Unable to open file " + string(filename);
    }
    return infile;
}

// Function to get the length of the file
int getFileLength(ifstream &infile) {
    infile.seekg(0, ios::end);
    int length = infile.tellg();
    infile.seekg(0, ios::beg);
    return length;
}

// Function to read data into a buffer
void readData(ifstream &infile, char *buffer, int length, const char *filename) {
    infile.read(buffer, length);
    if (!infile.good()) {
        throw "Unable to read from file " + string(filename);
    }
}

// Function to read file content
char* readFileContent(const char *filename) {
    ifstream infile;
    try {
        // Open file
        infile = openFile(filename);

        // Get length of file
        int length = getFileLength(infile);

        // Allocate memory
        char *buffer = new char[length];

        // Read data from file
        readData(infile, buffer, length, filename);

        infile.close();
        return buffer;
    } catch (const char *str) {
        printf("Error: %s \n", str);
        infile.close();
        throw;
    } catch (...) {
        printf("Error occurred trying to read from file \n");
        infile.close();
        throw;
    }
}

