#include <iostream>

// Define the node structure
struct Node {
    int data;
    Node* next;
};

// Function prototype
int size(Node* head);

#ifndef UNIT_TEST

// Main method
int main() {
    // Sample linked list creation for demonstration
    Node* head = new Node;
    head->data = 1;
    head->next = new Node;
    head->next->data = 2;
    head->next->next = nullptr;

    std::cout << "Size of linked list: " << size(head) << std::endl;

    // Free the allocated memory
    delete head->next;
    delete head;

    return 0;
}

#endif

// Function to calculate the size of the linked list
int size(Node* head) {
    Node* current = head;
    int count = 0;
    while (current != nullptr) {
        count++;
        current = current->next;
    }
    return count;
}

