// Mutex to be shared by all tests
std::mutex test_mutex;

// Test 1: Mutex Initialization Test
void test_mutex_initialization() {
    // Normally handled by library/system,
    // ensuring initialized state when declared
    try {
        std::lock_guard<std::mutex> lock(test_mutex);
        std::cout << "Mutex successfully initialized and locked." << std::endl;
    } catch (...) {
        assert(false && "Mutex initialization failed.");
    }
}

// Test 2: Simultaneous Thread Execution
void test_simultaneous_thread_execution() {
    bool in_critical_section = false;

    auto critical_section_test = [&]() {
        std::lock_guard<std::mutex> lock(test_mutex);
        assert(!in_critical_section && "Simultaneous access detected.");
        in_critical_section = true;
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        in_critical_section = false;
    };

    std::thread t1(critical_section_test);
    std::thread t2(critical_section_test);

    t1.join();
    t2.join();
}

// Test 3: Thread Lock/Unlock Robustness
void test_thread_lock_unlock_robustness() {
    try {
        std::lock_guard<std::mutex> lock(test_mutex);
        throw std::runtime_error("Simulated exception");
    } catch (...) {
        // Ensure mutex is unlocked due to lock_guard's automatic behavior
        { std::lock_guard<std::mutex> lock(test_mutex); }
    }
}

