void test_resource_contention_and_priority() {
    auto lock_test = [&]() {
        std::lock_guard<std::mutex> lock(test_mutex);
    };

    std::thread threads[100];
    for (int i = 0; i < 100; ++i) {
        threads[i] = std::thread(lock_test);
    }

    for (int i = 0; i < 100; ++i) {
        threads[i].join();
    }
