#include <iostream>

// Abstracts the bit choice logic
int choose_bit(int reg_bit, int bit_number_from_elsewhere, bool need_to_shift) {
    if (need_to_shift) {
        reg_bit -= bit_number_from_elsewhere;
    }
    return reg_bit;
}

// Abstracts the IO register handling
unsigned int handle_io_register(unsigned int* r, int bit_number_from_elsewhere, bool need_to_shift) {
    int the_bit_number = choose_bit(5, bit_number_from_elsewhere, need_to_shift);
    if ((the_bit_number > 0) && (the_bit_number < 63)) {
        unsigned int the_bit = 1u << the_bit_number;
        *r |= the_bit;
        return the_bit;
    }
    return 0;
}

